import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../core/api_paths.dart';import '../../core/providers.dart';import '../../widgets/async_panel.dart';
class TasksScreen extends ConsumerStatefulWidget{const TasksScreen({super.key});@override ConsumerState<TasksScreen> createState()=>_TasksScreenState();}
class _TasksScreenState extends ConsumerState<TasksScreen>{int refresh=0;@override Widget build(BuildContext context){final api=ref.watch(apiClientProvider);return AsyncPanel(key:ValueKey(refresh),future:api.get(ApiPaths.communicationSummary),builder:(context,data){final d=Map<String,dynamic>.from(data as Map);final tasks=(d['tasks'] as List).map((e)=>Map<String,dynamic>.from(e as Map)).toList();return ListView(padding:const EdgeInsets.all(16),children:[Text('Tasks',style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:12),if(tasks.isEmpty)const Card(child:ListTile(title:Text('Koi pending task nahi hai.'))),...tasks.map((t)=>Card(margin:const EdgeInsets.only(bottom:8),child:ListTile(title:Text('${t['title']}'),subtitle:Text('${t['type']} · Due ${t['due_at']??'-'}'),trailing:IconButton(icon:const Icon(Icons.check_circle_outline),onPressed:()=>_complete(int.parse('${t['id']}'))))))]);});}
 Future<void> _complete(int id) async{await ref.read(apiClientProvider).post(ApiPaths.taskComplete(id),data:const {});if(mounted)setState(()=>refresh++);}}
